    11|class AcousticalEditor : public juce::AudioProcessorEditor, private juce::Timer {
    12|public:
    13|    explicit AcousticalEditor(AcousticalAudioProcessor& p)
    14|        : AudioProcessorEditor(p), processor_(p) {
    15|        theme::apply(*this);
    16|
    17|        eqCanvas_ = std::make_unique<EqCanvas>([this](int band, float gain) {
    18|            processor_.engine().setBandGain(band, gain);
    19|        });
    20|        addAndMakeVisible(*eqCanvas_);
    21|
    22|        for (int i = 0; i < 3; ++i) {
    23|            DynamicEqCard::Snapshot snap;
    24|            snap.title = juce::String("Ecu dinámico ") + juce::String(i + 1);
    25|            snap.directionLabel = i == 0 ? "Donde más se necesita"
    26|                                : i == 1 ? "Empezando por los graves"
    27|                                         : "Empezando por los agudos";
    28|            snap.accent = i == 0 ? theme::eq1Cyan : i == 1 ? theme::eq2Amber : theme::eq3Magenta;
    29|            cards_[i] = std::make_unique<DynamicEqCard>(snap);
    30|            addAndMakeVisible(*cards_[i]);
    31|        }
    32|        startTimerHz(15);
    33|        setSize(900, 560);
    34|    }
    35|
    36|    void paint(juce::Graphics& g) override {
    37|        g.setColour(theme::background);
    38|        g.fillRect(getLocalBounds());
    39|    }
    40|
    41|    void resized() override {
    42|        auto bounds = getLocalBounds();
    43|        const int cardsH = 150;
    44|        auto cardsRow = bounds.removeFromBottom(cardsH);
    45|        const int w = getWidth() / 3;
    46|        for (int i = 0; i < 3; ++i)
    47|            cards_[i]->setBounds(cardsRow.removeFromLeft(w).reduced(4));
    48|        eqCanvas_->setBounds(bounds.reduced(6));
    49|    }
