    53|        acoustical::AnalysisResult analysis;
    54|        acoustical::SweepStep sweeps[3];
    55|        processor_.getLatestAnalysis(analysis, sweeps);
    56|
    57|        EqCanvas::Snapshot snap;
    58|        snap.bandFrequencies = processor_.engine().bandFrequencies();
    59|        snap.gains = analysis.combinedGainsL;
    60|        snap.gainsR = analysis.combinedGainsR;
    61|        snap.maxGainDb = processor_.engine().config().maxGainDb;
    62|        for (int i = 0; i < 3; ++i) {
    63|            if (sweeps[i].bandIndex >= 0
