    65|                snap.highlights[sweeps[i].bandIndex] =
    66|                    i == 0 ? theme::eq1Cyan : i == 1 ? theme::eq2Amber : theme::eq3Magenta;
    67|        }
    68|        eqCanvas_->setSnapshot(snap);
    69|
