    76|            card.accent = i == 0 ? theme::eq1Cyan : i == 1 ? theme::eq2Amber : theme::eq3Magenta;
    77|            card.maxGainDb = processor_.engine().config().maxGainDb;
    78|            if (analysis.dynamicEqGainsL.size() > static_cast<size_t>(i))
