     2|// Detecta la conexión del móvil (adb), reenvía puertos, sincroniza perfiles y
     3|// ajustes por JSON, y se auto-actualiza descargando el instalador de Windows
     4|// desde el propio móvil (verificación SHA-256 antes de ejecutar nada).
     5|#pragma once
     6|
     7|#include <juce_core/juce_core.h>
     8|#include <atomic>
     9|#include <functional>
    10|#include <mutex>
    11|#include <thread>
    12|
    13|class PhoneLink : private juce::Timer {
    14|public:
    15|    enum class State { NoAdb, WaitingForPhone, Connected, SyncError };
    16|
    17|    struct Listener {
    18|        virtual ~Listener() = default;
    19|        virtual void phoneStateChanged(State newState, const juce::String& info) = 0;
    20|        virtual void syncReceived(const juce::var& payload) = 0;
    21|    };
    22|
    23|    // Lo que el móvil anuncia sobre la versión de Windows disponible
    24|    struct WindowsUpdateInfo {
    25|        juce::String version;     // "" = el móvil no lleva paquete
    26|        juce::String sha256;
    27|        juce::int64 sizeBytes = 0;
    28|        bool hasPayload = false;
    29|        juce::String url;
    30|    };
    31|
    32|    explicit PhoneLink(juce::File adbExecutable);
    33|    ~PhoneLink() override;
    34|
    35|    void startWatchdog();          // sondea `adb devices` cada 1 s
    36|    void stopWatchdog();
    37|
    38|    State state() const { return state_.load(); }
    39|    juce::String deviceSerial() const { return deviceSerial_; }
    40|    juce::String lastSyncInfo() const;
    41|
    42|    // Sincronización: envía el estado actual y pide el del móvil
    43|    bool pushSync(const juce::var& payload);
    44|    bool requestSync();
    45|
    46|    // Comprueba con el móvil si hay una versión nueva de Windows; si la hay,
