    virtual ASIOError getChannelInfo(ASIOChannelInfo* info) = 0;
    virtual ASIOError createBuffers(ASIOBufferInfo* infos, long numChannels,
                                    long bufferSize, ASIOCallbacks* callbacks) = 0;
